import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.BTjPRYTP.js";const u=JSON.parse('{"title":"Fleet Telemetry","description":"","frontmatter":{},"headers":[],"relativePath":"guide/fleet-telemetry.md","filePath":"guide/fleet-telemetry.md"}'),n={name:"guide/fleet-telemetry.md"};function l(r,e,o,h,d,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="fleet-telemetry" tabindex="-1">Fleet Telemetry <a class="header-anchor" href="#fleet-telemetry" aria-label="Permalink to &quot;Fleet Telemetry&quot;">​</a></h1><p>Tesla Fleet Telemetry is an alternative to the standard polling approach. Instead of TeslaSync periodically requesting data from the Tesla Fleet API, vehicles <strong>push</strong> data directly to a telemetry server via a persistent streaming connection.</p><h2 id="why-fleet-telemetry" tabindex="-1">Why Fleet Telemetry? <a class="header-anchor" href="#why-fleet-telemetry" aria-label="Permalink to &quot;Why Fleet Telemetry?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Polling (default)</th><th>Fleet Telemetry</th></tr></thead><tbody><tr><td>Data resolution</td><td>30 s (driving)</td><td><strong>~1 s</strong></td></tr><tr><td>API cost (per vehicle/month)</td><td>~$15–25</td><td><strong>~$0.50</strong></td></tr><tr><td>Latency</td><td>Poll interval dependent</td><td><strong>Near real-time</strong></td></tr><tr><td>Wake-up required</td><td>Yes</td><td>No (streams when online)</td></tr><tr><td>Setup complexity</td><td>Low</td><td>Medium</td></tr></tbody></table><h3 id="cost-comparison" tabindex="-1">Cost Comparison <a class="header-anchor" href="#cost-comparison" aria-label="Permalink to &quot;Cost Comparison&quot;">​</a></h3><p>With standard polling TeslaSync makes thousands of Fleet API requests per month per vehicle. Tesla charges ~$0.00222 per request, so a single vehicle can cost <strong>$15–25/month</strong> depending on driving habits.</p><p>Fleet Telemetry replaces most of those requests with a single persistent connection. You still need a handful of API calls for commands and initial setup, but data ingestion is essentially <strong>free</strong> — reducing costs by up to <strong>97%</strong>.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────┐        wss        ┌────────────────────┐</span></span>
<span class="line"><span>│  Vehicle  │ ──────────────▶  │  Fleet Telemetry   │</span></span>
<span class="line"><span>│  (Tesla)  │   streaming      │  Server            │</span></span>
<span class="line"><span>└──────────┘                   └────────┬───────────┘</span></span>
<span class="line"><span>                                        │  protobuf / JSON</span></span>
<span class="line"><span>                                        ▼</span></span>
<span class="line"><span>                               ┌────────────────────┐</span></span>
<span class="line"><span>                               │    TeslaSync        │</span></span>
<span class="line"><span>                               │    (consumer)       │</span></span>
<span class="line"><span>                               └────────────────────┘</span></span></code></pre></div><p>The Fleet Telemetry server is a separate process that Tesla&#39;s vehicles connect to. TeslaSync subscribes to the telemetry stream to ingest data.</p><h2 id="setup-guide" tabindex="-1">Setup Guide <a class="header-anchor" href="#setup-guide" aria-label="Permalink to &quot;Setup Guide&quot;">​</a></h2><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>A <strong>Tesla Developer account</strong> with Fleet Telemetry access</li><li>A domain with a valid <strong>TLS certificate</strong> (vehicles connect via <code>wss://</code>)</li><li>A server reachable from the internet (or via Tesla&#39;s proxy)</li></ul><h3 id="step-1-—-deploy-the-telemetry-server" tabindex="-1">Step 1 — Deploy the Telemetry Server <a class="header-anchor" href="#step-1-—-deploy-the-telemetry-server" aria-label="Permalink to &quot;Step 1 — Deploy the Telemetry Server&quot;">​</a></h3><p>Clone and deploy the official telemetry server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/teslamotors/fleet-telemetry.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fleet-telemetry</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Follow the README for build &amp; deployment instructions</span></span></code></pre></div><p>The server listens for incoming WebSocket connections from vehicles and forwards records to a configurable datastore.</p><h3 id="step-2-—-configure-your-tesla-developer-account" tabindex="-1">Step 2 — Configure Your Tesla Developer Account <a class="header-anchor" href="#step-2-—-configure-your-tesla-developer-account" aria-label="Permalink to &quot;Step 2 — Configure Your Tesla Developer Account&quot;">​</a></h3><ol><li>Log in to <a href="https://developer.tesla.com" target="_blank" rel="noreferrer">developer.tesla.com</a></li><li>Navigate to your application settings</li><li>Add your telemetry server&#39;s public URL as the <strong>Fleet Telemetry endpoint</strong></li><li>Ensure the endpoint uses <code>wss://</code> and has a valid TLS certificate</li></ol><h3 id="step-3-—-pair-vehicles" tabindex="-1">Step 3 — Pair Vehicles <a class="header-anchor" href="#step-3-—-pair-vehicles" aria-label="Permalink to &quot;Step 3 — Pair Vehicles&quot;">​</a></h3><p>Each vehicle must be paired with your telemetry server. Use the Tesla Fleet API:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://fleet-api.prd.na.vn.cloud.tesla.com/api/1/vehicles/{id}/fleet_telemetry_config&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TESLA_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;vins&quot;: [&quot;YOUR_VIN&quot;],</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;config&quot;: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;hostname&quot;: &quot;telemetry.example.com&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;port&quot;: 443,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;ca&quot;: &quot;... your CA cert ...&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;fields&quot;: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;VehicleSpeed&quot;: { &quot;interval_seconds&quot;: 1 },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;Location&quot;: { &quot;interval_seconds&quot;: 1 },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;BatteryLevel&quot;: { &quot;interval_seconds&quot;: 10 },</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;ChargeState&quot;: { &quot;interval_seconds&quot;: 10 }</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      }</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    }</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><h3 id="step-4-—-configure-teslasync" tabindex="-1">Step 4 — Configure TeslaSync <a class="header-anchor" href="#step-4-—-configure-teslasync" aria-label="Permalink to &quot;Step 4 — Configure TeslaSync&quot;">​</a></h3><p>In the TeslaSync <strong>Settings</strong> page, enable <strong>Fleet Telemetry (Beta)</strong> and enter your telemetry server URL (e.g., <code>wss://telemetry.example.com</code>).</p><p>TeslaSync will subscribe to the telemetry stream and automatically ingest data when vehicles are online.</p><h3 id="step-5-—-verify" tabindex="-1">Step 5 — Verify <a class="header-anchor" href="#step-5-—-verify" aria-label="Permalink to &quot;Step 5 — Verify&quot;">​</a></h3><p>Once a vehicle is online and paired, data should begin streaming within seconds. Check the TeslaSync dashboard for real-time updates with 1-second resolution.</p><h2 id="telemetry-fields" tabindex="-1">Telemetry Fields <a class="header-anchor" href="#telemetry-fields" aria-label="Permalink to &quot;Telemetry Fields&quot;">​</a></h2><p>Fleet Telemetry supports a wide range of vehicle data fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Typical Interval</th></tr></thead><tbody><tr><td><code>VehicleSpeed</code></td><td>Current speed</td><td>1 s</td></tr><tr><td><code>Location</code></td><td>GPS coordinates</td><td>1 s</td></tr><tr><td><code>BatteryLevel</code></td><td>State of charge (%)</td><td>10 s</td></tr><tr><td><code>ChargeState</code></td><td>Charging status</td><td>10 s</td></tr><tr><td><code>Odometer</code></td><td>Total distance</td><td>60 s</td></tr><tr><td><code>InsideTemp</code></td><td>Cabin temperature</td><td>30 s</td></tr><tr><td><code>OutsideTemp</code></td><td>Ambient temperature</td><td>30 s</td></tr><tr><td><code>TirePressure</code></td><td>All four tires</td><td>60 s</td></tr></tbody></table><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="vehicle-not-connecting" tabindex="-1">Vehicle not connecting <a class="header-anchor" href="#vehicle-not-connecting" aria-label="Permalink to &quot;Vehicle not connecting&quot;">​</a></h3><ul><li>Ensure your TLS certificate is valid and the domain resolves correctly</li><li>Check that the vehicle has been paired via the Fleet API</li><li>Vehicles only stream when <strong>online</strong> — a sleeping vehicle will not connect</li></ul><h3 id="data-not-appearing-in-teslasync" tabindex="-1">Data not appearing in TeslaSync <a class="header-anchor" href="#data-not-appearing-in-teslasync" aria-label="Permalink to &quot;Data not appearing in TeslaSync&quot;">​</a></h3><ul><li>Verify the telemetry server URL in Settings matches your deployment</li><li>Check the telemetry server logs for incoming connections</li><li>Ensure TeslaSync can reach the telemetry server (network/firewall rules)</li></ul><h3 id="high-latency" tabindex="-1">High latency <a class="header-anchor" href="#high-latency" aria-label="Permalink to &quot;High latency&quot;">​</a></h3><ul><li>Fleet Telemetry should deliver sub-second latency</li><li>If latency is high, check network conditions between the telemetry server and TeslaSync</li></ul>`,37)])])}const y=t(n,[["render",l]]);export{u as __pageData,y as default};
